[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RuntimePath,[Parameter(Mandatory=$true)][string]$AssemblyDirectory,[Parameter(Mandatory=$true)][string]$ResultsPath)
$ErrorActionPreference='Stop'
function Quote-Collect([string]$Text){"'"+$Text.Replace("'","''")+"'"}
$inputPath=[IO.Path]::ChangeExtension($ResultsPath,'input.ps1')
$commands=@(
    ('. '+(Quote-Collect (Join-Path $PSScriptRoot 'CollectLoopSetup.ps1'))+' -AssemblyDirectory '+(Quote-Collect $AssemblyDirectory)),
    '& { [DisplayHostContract.Row]::new(''end-a'',''one''); [DisplayHostContract.Row]::new(''end-b'',''one'') }',
    'Assert-Collect ''Collect_EndOfSubmission_RendersOneOriginalBatch'' ($global:CollectBatches.Count -eq 1 -and $global:CollectBatches[0] -eq ''end-a,end-b'' -and (Test-CollectOrder @(''COLLECT<end-a,end-b>'')))',
    '[DisplayHostContract.Row]::new(''gap-c'',''a'')',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''CompletedRichFrames_IncludeOneBlankPhysicalLine'' (($screen.IndexOf(''COLLECT<gap-c>'')-$screen.IndexOf(''COLLECT<end-a,end-b>'')) -eq (2*[Console]::BufferWidth))',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''scope-a'',''a''); [DisplayHostContract.Row]::new(''scope-b'',''b''); ''native-boundary''; [DisplayHostContract.Row]::new(''scope-c'',''b'') }',
    'Assert-Collect ''Collect_ScopeAndNativeTypeBoundaries_CloseInOrder'' ($global:CollectBatches.Count -eq 3 -and (Test-CollectOrder @(''COLLECT<scope-a>'',''COLLECT<scope-b>'',''native-boundary'',''COLLECT<scope-c>'')))',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''error-a'',''a''); Write-Error ''COLLECT_ERROR'' -ErrorAction Continue; [DisplayHostContract.Row]::new(''error-b'',''a'') }',
    'Assert-Collect ''Collect_AutomaticUnmergedError_FlushesBeforeError'' ($global:CollectBatches.Count -eq 2 -and (Test-CollectOrder @(''COLLECT<error-a>'',''COLLECT_ERROR'',''COLLECT<error-b>'')))',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''stop-a'',''a''); throw ''COLLECT_TERMINATING_ERROR'' }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_TerminatingError_AbortsIncompleteBatchWithoutLateFrame'' ($global:CollectBatches.Count -eq 0 -and $screen -match ''COLLECT_TERMINATING_ERROR'' -and $screen -notmatch ''COLLECT<stop-a>'')',
    'Use-CollectView; [ConsoleMonster.PowerShell.Display.DefaultDisplay]::SetMode(''Off'',$null); $stopNative=[DisplayHostContract.Row]::new(''native-stop-a'',''a'')',
    '& { $stopNative; throw ''NATIVE_TERMINATING_ERROR'' }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Native_TerminatingError_AlsoOmitsIncompleteFormattedRow'' (-not $screen.Contains(''native-stop-a'') -and $screen -match ''NATIVE_TERMINATING_ERROR''); [ConsoleMonster.PowerShell.Display.DefaultDisplay]::SetMode(''Auto'',$null)',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''merged-stop-a'',''a''); throw ''MERGED_TERMINATING_ERROR'' } *>&1',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_MergedTerminatingProducer_HasNoCompletedOrLateFrame'' ($global:CollectBatches.Count -eq 0 -and $screen -match ''MERGED_TERMINATING_ERROR'' -and $screen -notmatch ''COLLECT<merged-stop-a>'')',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''independent-a'',''a''); Write-Warning ''INDEPENDENT_WARNING''; Write-Verbose ''INDEPENDENT_VERBOSE'' -Verbose; Write-Information ''INDEPENDENT_INFORMATION'' -InformationAction Continue; [DisplayHostContract.Row]::new(''independent-b'',''a'') }',
    'Assert-Collect ''Collect_UnmergedWarningVerboseInformation_KeepNativeTiming'' ($global:CollectBatches.Count -eq 1 -and (Test-CollectOrder @(''INDEPENDENT_WARNING'',''INDEPENDENT_VERBOSE'',''INDEPENDENT_INFORMATION'',''COLLECT<independent-a,independent-b>'')))',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''merged-a'',''a''); Write-Warning ''MERGED_WARNING''; [DisplayHostContract.Row]::new(''merged-b'',''a''); Write-Verbose ''MERGED_VERBOSE'' -Verbose; [DisplayHostContract.Row]::new(''merged-c'',''a''); Write-Information ''MERGED_INFORMATION'' -InformationAction Continue; [DisplayHostContract.Row]::new(''merged-d'',''a''); Write-Error ''MERGED_ERROR'' -ErrorAction Continue; [DisplayHostContract.Row]::new(''merged-e'',''a'') } *>&1',
    'Assert-Collect ''Collect_AllMergedRecords_PreserveProducerOrder'' ($global:CollectBatches.Count -eq 5 -and (Test-CollectOrder @(''COLLECT<merged-a>'',''MERGED_WARNING'',''COLLECT<merged-b>'',''MERGED_VERBOSE'',''COLLECT<merged-c>'',''MERGED_INFORMATION'',''COLLECT<merged-d>'',''MERGED_ERROR'',''COLLECT<merged-e>'')))',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''merged2-a'',''a''); Write-Error ''MERGED2_ERROR'' -ErrorAction Continue; [DisplayHostContract.Row]::new(''merged2-b'',''a'') } 2>&1',
    'Assert-Collect ''Collect_ErrorOnlyMerged_PreservesProducerOrder'' ($global:CollectBatches.Count -eq 2 -and (Test-CollectOrder @(''COLLECT<merged2-a>'',''MERGED2_ERROR'',''COLLECT<merged2-b>'')))',
    'Use-CollectView',
    '& { foreach($i in 1..2000){[DisplayHostContract.Row]::new((''exact{0:d4}'' -f $i),''a'')} }',
    'Assert-Collect ''Collect_Exactly2000Records_RendersOneBoundedBatch'' ($global:CollectBatches.Count -eq 1 -and $global:CollectBatches[0] -eq ''2000:exact0001:exact2000'')',
    'Use-CollectView',
    '& { foreach($i in 1..2001){[DisplayHostContract.Row]::new((''over{0:d4}'' -f $i),''a'')} }',
    'Assert-Collect ''Collect_RecordBudgetExceeded_ReplaysFromFirstAndPrintsCount'' ($global:CollectBatches.Count -eq 0 -and (Test-CollectOrder @(''over0001'',''over2001'',''2001 rows'')))',
    'Use-CollectView -Bytes 512',
    '& { [DisplayHostContract.Row]::new(''byte-first'',''a''); [DisplayHostContract.Row]::new((''byte-over-''+(''x''*300)),''a''); [DisplayHostContract.Row]::new(''byte-last'',''a'') }',
    'Assert-Collect ''Collect_ByteBudgetExceeded_ReplaysPrefixAndRemainderInOrder'' ($global:CollectBatches.Count -eq 0 -and (Test-CollectOrder @(''byte-first'',''byte-over-'',''byte-last'',''3 rows'')))',
    'Use-CollectView; $huge=[DisplayHostContract.Row]::new((''ceiling16mb-''+(''x''*8388608)),''a'')',
    '$huge',
    'Assert-Collect ''Collect_16MiBCeiling_DelegatesOversizedRecordNatively'' ($global:CollectBatches.Count -eq 0 -and (Test-CollectOrder @(''ceiling16mb-'',''1 rows''))); $huge=$null',
    'Use-CollectView -View collect.failure; $global:CollectBroken=$true; $VerbosePreference=''Continue''',
    '& { [DisplayHostContract.Row]::new(''fallback-a'',''a''); [DisplayHostContract.Row]::new(''fallback-b'',''a''); ''failure-boundary''; [DisplayHostContract.Row]::new(''fallback-c'',''a'') }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_WidgetThrows_NoPartialFrameOriginalOrderAndOneDiagnostic'' (($screen -notmatch ''PARTIAL_RICH_MUST_NOT_APPEAR'') -and ([regex]::Matches($screen,''used native formatting'').Count -eq 1) -and (Test-CollectOrder @(''fallback-a'',''fallback-b'',''failure-boundary'',''fallback-c''))); $global:CollectBroken=$false',
    'Use-CollectView -Bytes 1024 -View collect.outputbudget; $global:CollectLarge=$true',
    '& { [DisplayHostContract.Row]::new(''encoded-a'',''a''); [DisplayHostContract.Row]::new(''encoded-b'',''a'') }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_FullEncodedBudgetExceeded_FallsBackWithoutPartialFrame'' (($screen -notmatch ''zzzzzzzz'') -and (Test-CollectOrder @(''encoded-a'',''encoded-b''))); $global:CollectLarge=$false',
    'Use-CollectView; $original=[DisplayHostContract.Row]::new(''identity-row'',''a''); $names=@($original.PSObject.TypeNames); $assigned=$original; $native=$original|Out-String; $formatted=$original|Format-Table Name|Out-String; $json=$original|ConvertTo-Json -Compress',
    'Assert-Collect ''Collect_CaptureFormatSerialization_PreserveIdentityAndNativeSinks'' ($global:CollectBatches.Count -eq 0 -and [object]::ReferenceEquals($original,$assigned) -and ($names -join ''|'') -ceq ($original.PSObject.TypeNames -join ''|'') -and $native -match ''identity-row'' -and $formatted -match ''identity-row'' -and $json -match ''identity-row'')',
    'Use-CollectView',
    ('Start-Transcript -LiteralPath '+(Quote-Collect ([IO.Path]::ChangeExtension($ResultsPath,'transcript.txt')))+'|Out-Null'),
    '[DisplayHostContract.Row]::new(''transcript-collect'',''a'')',
    'Stop-Transcript|Out-Null; Assert-Collect ''Collect_ActiveTranscript_DoesNotInvokeBuilder'' ($global:CollectBatches.Count -eq 0)',
    'Use-CollectView; $env:CI=''1''',
    '[DisplayHostContract.Row]::new(''ci-collect'',''a'')',
    'Assert-Collect ''Collect_CI_DoesNotInvokeBuilder'' ($global:CollectBatches.Count -eq 0); $env:CI=$null',
    'Use-CollectView; $env:NO_COLOR=''1''; [ConsoleMonster.Terminal]::Refresh()',
    '& { [DisplayHostContract.Row]::new(''plain-a'',''a''); [DisplayHostContract.Row]::new(''plain-b'',''a'') }',
    'Assert-Collect ''Collect_NoColorPhysicalHost_KeepsLayoutInPlainMode'' ($global:CollectBatches.Count -eq 1 -and $global:CollectMode -eq ''Plain'')',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''status-a'',''a''); Start-Sleep -Milliseconds 1100; [DisplayHostContract.Row]::new(''status-b'',''a''); $global:StatusObserved=Read-CollectStatus; Write-Warning ''STATUS_WARNING''; Write-Verbose ''STATUS_VERBOSE'' -Verbose; Write-Information ''STATUS_INFORMATION'' -InformationAction Continue; [DisplayHostContract.Row]::new(''status-c'',''a'') }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_StatusLine_CompleteOwnedLineErasedNativeMessagesIntact'' ($global:StatusObserved -and $screen -notmatch ''collecting'' -and ($screen.IndexOf(''WARNING: STATUS_WARNING'') % [Console]::BufferWidth) -eq 0 -and (Test-CollectOrder @(''STATUS_WARNING'',''STATUS_VERBOSE'',''STATUS_INFORMATION'',''COLLECT<status-a,status-b,status-c>'')))',
    'Use-CollectView',
    '& { [DisplayHostContract.Row]::new(''aborted-status-a'',''a''); Start-Sleep -Milliseconds 1100; [DisplayHostContract.Row]::new(''aborted-status-b'',''a''); $global:AbortedStatusObserved=Read-CollectStatus; throw ''ABORTED_STATUS_ERROR'' }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_AbortedProducer_ReleasesVisibleStatusWithoutLateFrame'' ($global:AbortedStatusObserved -and $screen -notmatch ''collecting'' -and $screen -match ''ABORTED_STATUS_ERROR'' -and $screen -notmatch ''COLLECT<aborted-status'')',
    'Use-CollectView; $env:NO_COLOR=$null; [ConsoleMonster.Terminal]::Refresh(); $savedForeground=$Host.UI.RawUI.ForegroundColor; $Host.UI.RawUI.ForegroundColor=[ConsoleColor]::White; if($PSVersionTable.PSVersion.Major -ge 7){$savedStyle=$PSStyle.OutputRendering; $PSStyle.OutputRendering=''PlainText''}else{$global:CollectLease.Mode=''Plain''}',
    '& { [DisplayHostContract.Row]::new(''style-a'',''a''); Start-Sleep -Milliseconds 1100; [DisplayHostContract.Row]::new(''style-b'',''a''); $global:PlainStatusObserved=Read-PlainCollectStatus }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_PlainPreference_StatusAndFrameRemainUndecorated'' ($global:PlainStatusObserved -and $global:CollectMode -eq ''Plain'' -and $screen -notmatch ''collecting''); $Host.UI.RawUI.ForegroundColor=$savedForeground; if($PSVersionTable.PSVersion.Major -ge 7){$PSStyle.OutputRendering=$savedStyle}else{$global:CollectLease.Mode=''Auto''}',
    'Use-CollectView; $Host.UI.RawUI.CursorPosition=[Management.Automation.Host.Coordinates]::new(0,$Host.UI.RawUI.BufferSize.Height-1)',
    '& { [DisplayHostContract.Row]::new(''bottom-a'',''a''); Start-Sleep -Milliseconds 1100; [DisplayHostContract.Row]::new(''bottom-b'',''a''); $global:BottomStatusObserved=Read-CollectStatus }',
    '$screen=[DisplayHostContract.ConsoleText]::Read(); Assert-Collect ''Collect_StatusWithoutSparePhysicalLine_FailsClosed'' (-not $global:BottomStatusObserved -and $screen -notmatch ''collecting'' -and $global:CollectBatches.Count -eq 1)',
    '$global:CollectLease.Dispose()',
    ('[pscustomobject]@{Runtime=$PSVersionTable.PSVersion.ToString();RecordedUtc=[DateTime]::UtcNow.ToString(''o'');Tests=$global:DisplayLoopResults.ToArray();Failed=@($global:DisplayLoopResults|Where-Object{-not $_.Passed}).Count}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath '+(Quote-Collect $ResultsPath)+' -Encoding UTF8'),
    'exit'
)
[IO.File]::WriteAllLines($inputPath,$commands)
$started=[DateTime]::UtcNow
$process=Start-Process -FilePath $RuntimePath -ArgumentList @('-NoLogo','-NoProfile','-Command','-') -RedirectStandardInput $inputPath -WindowStyle Hidden -PassThru
[pscustomobject]@{OwnedPid=$process.Id;Results=$ResultsPath}|ConvertTo-Json -Compress
if(-not $process.WaitForExit(45000)){Stop-Process -Id $process.Id;throw 'The owned Collect test exceeded 45 seconds.'}
$process.Refresh()
$report=Get-Content -LiteralPath $ResultsPath -Raw|ConvertFrom-Json
$report.Tests|Format-Table Name,Passed -AutoSize
if($process.ExitCode -ne 0 -or $report.Failed -or $report.Tests.Count -ne 24 -or [DateTime]$report.RecordedUtc -lt $started){throw 'Collect host proof failed; see its result file.'}
